#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/cuda/type_converters.h>

namespace {

template <typename B>
using sync_class =
    py::class_<B, gr::sync_block, gr::block, gr::basic_block, std::shared_ptr<B>>;

template <typename B>
void bind_vlen(py::module& m, const char* name)
{
    sync_class<B>(m, name).def(py::init(&B::make), py::arg("vlen") = 1);
}

template <typename B>
void bind_scaled(py::module& m, const char* name)
{
    sync_class<B>(m, name)
        .def(py::init(&B::make), py::arg("vlen") = 1, py::arg("scale") = 1.0f)
        .def("scale", &B::scale)
        .def("set_scale", &B::set_scale, py::arg("scale"));
}

template <typename B>
void bind_to_interleaved(py::module& m, const char* name)
{
    py::class_<B,
               gr::sync_interpolator,
               gr::sync_block,
               gr::block,
               gr::basic_block,
               std::shared_ptr<B>>(m, name)
        .def(py::init(&B::make),
             py::arg("vector") = false,
             py::arg("scale_factor") = 1.0f)
        .def("scale_factor", &B::scale_factor)
        .def("set_scale_factor", &B::set_scale_factor, py::arg("scale_factor"));
}

template <typename B>
using decim_class = py::class_<B,
                               gr::sync_decimator,
                               gr::sync_block,
                               gr::block,
                               gr::basic_block,
                               std::shared_ptr<B>>;

template <typename B>
void add_interleaved_accessors(decim_class<B>& c)
{
    c.def("scale_factor", &B::scale_factor)
        .def("swap", &B::swap)
        .def("set_scale_factor", &B::set_scale_factor, py::arg("scale_factor"))
        .def("set_swap", &B::set_swap, py::arg("swap"));
}

} // namespace

void bind_type_converters(py::module& m)
{
    using namespace gr::cuda;

    bind_scaled<char_to_float>(m, "char_to_float");
    bind_scaled<uchar_to_float>(m, "uchar_to_float");
    bind_scaled<short_to_float>(m, "short_to_float");
    bind_scaled<int_to_float>(m, "int_to_float");
    bind_scaled<float_to_char>(m, "float_to_char");
    bind_scaled<float_to_short>(m, "float_to_short");
    bind_scaled<float_to_int>(m, "float_to_int");

    sync_class<float_to_uchar>(m, "float_to_uchar")
        .def(py::init(&float_to_uchar::make),
             py::arg("vlen") = 1,
             py::arg("scale") = 1.0f,
             py::arg("bias") = 0.0f)
        .def("scale", &float_to_uchar::scale)
        .def("bias", &float_to_uchar::bias)
        .def("set_scale", &float_to_uchar::set_scale, py::arg("scale"))
        .def("set_bias", &float_to_uchar::set_bias, py::arg("bias"));

    bind_vlen<char_to_short>(m, "char_to_short");
    bind_vlen<short_to_char>(m, "short_to_char");
    bind_vlen<float_to_complex>(m, "float_to_complex");
    bind_vlen<complex_to_float>(m, "complex_to_float");
    bind_vlen<complex_to_real>(m, "complex_to_real");
    bind_vlen<complex_to_imag>(m, "complex_to_imag");
    bind_vlen<complex_to_mag>(m, "complex_to_mag");
    bind_vlen<complex_to_mag_squared>(m, "complex_to_mag_squared");
    bind_vlen<complex_to_arg>(m, "complex_to_arg");
    bind_vlen<complex_to_magphase>(m, "complex_to_magphase");
    bind_vlen<magphase_to_complex>(m, "magphase_to_complex");

    bind_to_interleaved<complex_to_interleaved_char>(m, "complex_to_interleaved_char");
    bind_to_interleaved<complex_to_interleaved_short>(m,
                                                      "complex_to_interleaved_short");

    decim_class<interleaved_char_to_complex> ichar(m, "interleaved_char_to_complex");
    ichar.def(py::init(&interleaved_char_to_complex::make),
              py::arg("vector_input") = false,
              py::arg("scale_factor") = 1.0f,
              py::arg("swap") = false);
    add_interleaved_accessors(ichar);

    decim_class<interleaved_short_to_complex> ishort(m, "interleaved_short_to_complex");
    ishort.def(py::init(&interleaved_short_to_complex::make),
               py::arg("vector_input") = false,
               py::arg("swap") = false,
               py::arg("scale_factor") = 1.0f);
    add_interleaved_accessors(ishort);
}
